const canonicalParameterValueSchema = z.union([
  z.string().max(256),
  z.number().finite(),
  z.boolean(),
  z.null(),
]);

function uniqueStrings(
  values: readonly string[],
  context: z.RefinementCtx,
  path: PropertyKey[],
): void {
  const seen = new Set<string>();
  for (const [index, value] of values.entries()) {
    if (seen.has(value)) {
      context.addIssue({ code: "custom", message: "值必须唯一。", path: [...path, index] });
    }
    seen.add(value);
  }
}

export const statisticalOperatorValueBindingSchema = z.strictObject({
  result_field: stableIdentifierSchema,
  operator_field: stableIdentifierSchema,
  comparison: z.enum(["EXACT", "NUMERIC_TOLERANCE"]),
  absolute_tolerance: z.number().finite().nonnegative().max(1),
  relative_tolerance: z.number().finite().nonnegative().max(1),
});

export const statisticalOperatorResultBindingSchema = z
  .strictObject({
    result_output_name: outputNameSchema,
    result_collection_path: jsonPointerSchema,
    operator_collection_path: jsonPointerSchema,
    label_fields: z.array(stableIdentifierSchema).min(1).max(8),
    value_bindings: z.array(statisticalOperatorValueBindingSchema).min(1).max(32),
    require_exact_label_set: z.literal(true),
  })
  .superRefine((binding, context) => {
    uniqueStrings(binding.label_fields, context, ["label_fields"]);
    uniqueStrings(
      binding.value_bindings.map(({ result_field }) => result_field),
      context,
      ["value_bindings"],
    );
    uniqueStrings(
      binding.value_bindings.map(({ operator_field }) => operator_field),
      context,
      ["value_bindings"],
    );
    for (const [index, valueBinding] of binding.value_bindings.entries()) {
      if (
        valueBinding.comparison === "EXACT" &&
        (valueBinding.absolute_tolerance !== 0 || valueBinding.relative_tolerance !== 0)
      ) {
        context.addIssue({
          code: "custom",
          message: "EXACT 绑定的容差必须为零。",
          path: ["value_bindings", index],
        });
      }
    }
  });

